import {EFFECTS,effectType,ensurePlugins} from './plugins.js';import {MASTER_MODULES,masteringSettings} from './mastering.js?v=0.15.12';import {validateRack,matchesTarget} from './war-rack-core.js';
export function captureRack({track=null,project=null,name,source,stage,genre='Tous',id='user-'+globalThis.crypto.randomUUID()}){if(typeof name!=='string'||!name.trim()||name.length>100)throw Error('Nom invalide');const state=track?structuredClone(track):masteringSettings(project?.mastering);if(track)ensurePlugins(state);else if(state.rackVersion===2)throw Error('Utilise « Sauver le rack » dans CHAYAH MASTER RACK pour conserver les voies, instances et macros.');const registry=track?EFFECTS:MASTER_MODULES,values=track?state.effects:state,stages=state.inserts.filter(id=>id&&values[id]?.enabled!==false).map(id=>{const type=track?effectType(id):id;return {id:type,values:Object.fromEntries(registry[type].controls.map(c=>[c.key,values[id][c.key]??c.default]))};});if(!stages.length)throw Error('Aucun insert actif à sauvegarder');const r={id,name:name.trim(),source,genre,stage,category:source,description:'Chaîne active sauvegardée par l’utilisateur',stages};if(!matchesTarget(r,track))throw Error('Destination incompatible');validateRack(r);return r;}
export function serializeRack(r){validateRack(r);return JSON.stringify({schema:'warlike.rack.v1',rack:r},null,2);}
export function parseRack(text){if(typeof text!=='string'||text.length>262144)throw Error('Preset invalide');const data=JSON.parse(text),r=data.rack;if(data.schema!=='warlike.rack.v1'||!r||typeof r.name!=='string'||r.name.length>100||typeof r.genre!=='string'||!Array.isArray(r.stages)||!r.stages.length)throw Error('Format rack invalide');const safe={id:'import-'+globalThis.crypto.randomUUID(),name:r.name,description:typeof r.description==='string'?r.description.slice(0,400):r.name,source:r.source,stage:r.stage,genre:r.genre,category:r.source,stages:r.stages.map(s=>({id:s.id,values:{...s.values}}))};validateRack(safe);return safe;}